import{_ as r,C as o,o as s,c as i,j as t,a as n,E as d,a6 as h}from"./chunks/framework.CCKCzdWs.js";const m=JSON.parse('{"title":"Run video","description":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends.","frontmatter":{"title":"Run video","description":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-video.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-video.html"}],["meta",{"property":"og:title","content":"Run video | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Play the videos Playwright recorded for a finished run, one test after another, beside a checklist that ticks as each test ends."}]]},"headers":[],"relativePath":"features/run-video.md","filePath":"features/run-video.md","lastUpdated":1794481239000}'),l={name:"features/run-video.md"};function c(u,e,f,p,v,k){const a=o("Needs");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"run-video",tabindex:"-1"},[n("Run video "),t("a",{class:"header-anchor",href:"#run-video","aria-label":'Permalink to "Run video"'},"​")],-1)),d(a,{reporter:""}),e[1]||(e[1]=h('<p>A finished run has a <strong>Video</strong> tab that plays the videos Playwright recorded for the run, one test after another, beside a checklist of the tests. A test is ticked as its video passes the end of the test, so you can follow a worker&#39;s run as it happened. The bar under the video has one block for each test, colored by its result. Click a test or the bar to jump there.</p><h2 id="group-by-worker-or-file" tabindex="-1">Group by Worker or File <a class="header-anchor" href="#group-by-worker-or-file" aria-label="Permalink to &quot;Group by Worker or File&quot;">​</a></h2><ul><li><strong>Worker</strong> plays one worker&#39;s tests in the order they ran. Pick the worker above the video.</li><li><strong>File</strong> plays every test in the order its file declares it, each marked with the worker it ran on. The tests ran in parallel, so this order is not the order they ran in.</li></ul><p>Only the final attempt of a test is listed. A test that has no video stays on the checklist and takes a small block on the bar. It is ticked as the reel moves on. The tab is off while the run is live.</p><h2 id="when-there-are-no-videos" tabindex="-1">When there are no videos <a class="header-anchor" href="#when-there-are-no-videos" aria-label="Permalink to &quot;When there are no videos&quot;">​</a></h2><p>Most suites record video only for failing tests (<code>video: &#39;retain-on-failure&#39;</code>), so a run where nothing failed often has none, and the tab says so. Set <code>video: &#39;on&#39;</code> in Playwright&#39;s <code>use</code> options to record every test. Videos can be large, so read <a href="/operate/storage.html#storage-management">storage cleanup</a> first.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./evidence.html">Failure evidence</a>: one failing execution, with its trace, screenshots and video</li><li><a href="/operate/storage.html#storage-management">Storage</a>: how long videos are kept</li></ul>',8))])}const y=r(l,[["render",c]]);export{m as __pageData,y as default};
